// Post covers are SVG illustrations, each shipped with a PNG sibling at the
// same path (cover.svg, cover.png). Crawlers and social cards want a raster,
// so anything that hands a cover to a machine (JSON-LD, OG, feeds) goes
// through here.
export function rasterCover(heroImage: string): string {
  return heroImage.replace(/\.svg(\?.*)?$/i, ".png$1");
}

// Every SVG cover also ships a dark-theme twin next to it (cover-dark.svg),
// generated by `pnpm covers:dark` with the three brand colours swapped for
// their night values. Raster covers have no twin.
export function darkCover(heroImage: string): string | null {
  return /\.svg(\?.*)?$/i.test(heroImage)
    ? heroImage.replace(/\.svg(\?.*)?$/i, "-dark.svg$1")
    : null;
}
